const brand = Color(0xFF252525);
const peach = Color(0xFFF4A58A);

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();
  await Firebase.initializeApp(); // Configure with `flutterfire configure` first.
  runApp(ChangeNotifierProvider(create: (_) => CartModel(), child: const PrintifyApp()));
}

class PrintifyApp extends StatelessWidget {
  const PrintifyApp({super.key});
  @override
  Widget build(BuildContext context) => MaterialApp(
    title: 'Printify', debugShowCheckedModeBanner: false,
    theme: ThemeData(useMaterial3: true, colorScheme: ColorScheme.fromSeed(seedColor: brand, primary: brand, secondary: peach), scaffoldBackgroundColor: const Color(0xFFFAF8F5), appBarTheme: const AppBarTheme(backgroundColor: Color(0xFFFAF8F5), foregroundColor: brand)),
    home: const AuthGate(),
  );
}

class CartModel extends ChangeNotifier {
  final Map<String, Map<String, dynamic>> _items = {};
  Map<String, Map<String, dynamic>> get items => Map.unmodifiable(_items);
  int get count => _items.values.fold(0, (a, b) => a + (b['qty'] as int));
  double get total => _items.values.fold(0, (a, b) => a + (b['price'] as num).toDouble() * (b['qty'] as int));
  void add(Map<String, dynamic> p) { final id = p['id'] as String; if (_items.containsKey(id)) { _items[id]!['qty'] = (_items[id]!['qty'] as int) + 1; } else { _items[id] = {...p, 'qty': 1}; } notifyListeners(); }
  void remove(String id) { _items.remove(id); notifyListeners(); }
  void clear() { _items.clear(); notifyListeners(); }
}

class AuthGate extends StatelessWidget {
  const AuthGate({super.key});
  @override
  Widget build(BuildContext context) => StreamBuilder<User?>(
    stream: FirebaseAuth.instance.authStateChanges(),
    builder: (context, snap) { if (snap.connectionState == ConnectionState.waiting) return const LoadingPage(); if (snap.data == null) return const SignInPage(); return const HomePage(); },
  );
}

class LoadingPage extends StatelessWidget { const LoadingPage({super.key}); @override Widget build(BuildContext context) => const Scaffold(body: Center(child: CircularProgressIndicator())); }

